      // On GB10 the driver occasionally returns ms==0 from
      // cudaEventElapsedTime (a non-deterministic event-timing glitch on
      // a kernel that plainly takes >0). Retry the launch once, clearing
      // any sticky error first, so a single bad reading cannot poison the
      // median with inf TFLOP/s.
      if (ms <= 0.0f) {
        (void)cudaGetLastError();
        cudaEventRecord(start);
        launch();
        cudaEventRecord(stop);
        cudaEventSynchronize(stop);
        cudaEventElapsedTime(&ms, start, stop);
      }
      times.push_back(ms * 1000.0f);
    }
    double sum = 0;
    for (double t : times) sum += t;
    double mean = sum / iters;
    double sum2 = 0;
    for (double t : times) sum2 += t * t;
    double var = sum2 / iters - mean * mean;
    double stddev = std::sqrt(std::max(0.0, var));
    if ((mean > 0 && stddev / mean < 0.03) || iters >= max_iters) {
      std::sort(times.begin(), times.end());
      return {times[0], times[iters / 2], mean};
    }
    iters *= 2;
  }
  return {};
}

