// vkernels/kernels/dsa.hpp
//
// DeepseekSparseAttn (DSA) sparse-MLA forward — the GLM-5.3-Flash / DeepSeek-V3
// sparse-attention path (issue #51). An *indexer* (out of scope here) has
// already selected, per query token, the top-`topk` most relevant KV tiles
// (`indices`). This kernel scores each query against those selected keys and
// produces the combined attention output.
//
// The query/key are `dim + tail_dim` wide and the value is `d_v = dim - tail_dim`
// wide (the absorbed-MLA form: the nope key latent IS the value, width `d_v`,
// and the decoupled RoPE key contributes the extra `tail_dim`). Both shapes
// MUST work:
//
//   * GLM-5.3-Flash : qk_nope_head_dim = v_head_dim = 256, qk_rope_head_dim = 0
//                     -> dim = 256, tail_dim = 0, d_v = 256. There is NO rope
//                        tail, so the tail QK dot is skipped entirely. This is
//                        the shape tilelang cannot compile (a zero-size
//                        `Q_tail_buf`/`K_tail_shared` GEMM); the HIP kernel
//                        below guards `tail_dim == 0` and skips that dot.
//   * DeepSeek-V3   : qk_nope_head_dim = v_head_dim = 512, qk_rope_head_dim = 64
//                     -> dim = 576, tail_dim = 64, d_v = 512.
//
// Tensors (kv_group == 1; all heads share one key/value head):
//
//   q       : [1, S_q,  H,  dim + tail_dim]  bf16 (device) / fp32 (oracle)
//             q[i,h] = [ q_main (dim)  |  q_tail (tail_dim) ]   (tail may be 0)
//   kv      : [1, S_kv, kv_group, dim + tail_dim]  bf16 / fp32
//             kv[j,0] = [ v (d_v)  |  k_nope_extra (tail_dim)  |  k_rope (tail_dim) ]
//             so v[j]    = kv[j][0 : d_v]              (the value)
//                k_main[j]= kv[j][0 : dim]             (nope key, width dim)
//                k_tail[j]= kv[j][dim : dim + tail_dim] (rope key, width tail_dim)
//   indices : [1, S_q, kv_group, topk]   int32  (padded to a multiple of 64;
//             entries < 0 or >= S_kv are masked kpool tail tokens)
//   out     : [1, S_q, H, d_v]           bf16 / fp32   (combined)
//   lse     : [1, S_q, H]                fp32, nullable  (base-2 log-sum-exp)
//
// Computation (per query token i, head h; the selected keys are gathered via
// `indices[i,0,k]`):
//
//   raw[i,h,k]   = q_main[i,h] . k_main[idx] + (tail_dim>0) q_tail[i,h] . k_tail[idx]
//   score[i,h,k] = sm_scale * raw[i,h,k]            (sm_scale includes log2(e))
//   w[i,h,k]     = 2^(score[i,h,k] - lse[i,h])       (masked keys -> weight 0)
//   out[i,h]     = Σ_k w[i,h,k] * v[idx]              (d_v wide)
//   lse[i,h]     = log2( Σ_k 2^score[i,h,k] )          (base-2, when return_lse)
//
// `sm_scale = (1 / sqrt(dim + tail_dim)) * log2(e)`, so the weights are the
// standard natural-exp softmax `exp(raw/sqrt(dim+tail_dim)) / Σ` expressed in
// base-2 (FlashAttention's log2 trick). Masked keys contribute weight 0; if
// every selected key is masked the output row is 0 and the LSE is -inf.
//
// Two-implementation model (mirrors mla.{hpp,cpp,hip} from issue #21):
//   dsa.cpp  -- CPU reference (oracle), always compiled, in vkernels::kernels.
//               Two-pass numerically-stable base-2 softmax, fp32 throughout.
//   dsa.hip  -- HIP kernel (gfx942), compiled with VKERNELS_HAS_HIP. Online
//               softmax, fp32 accumulation, bf16 storage. Each block owns one
//               (query, head) pair and streams its `topk` selected keys,
//               accumulating the combined output directly (the per-group
//               partial_o / partial_lse from the tilelang kernel are an
//               internal parallelism detail; the combined result is
//               grouping-independent). Matches the oracle within tolerance.
#include <cstddef>
#include <cstdint>

namespace vkernels::kernels {

// CPU reference (oracle). Computes the sparse-MLA forward in fp32 with a
// numerically-stable two-pass base-2 softmax over the `topk` selected keys.
//
//   d_v = dim - tail_dim   (must be > 0; tail_dim may be 0)
//   topk % (block_I * inner_iter) must be 0 (the kernel's group tiling; the
//       oracle result is grouping-independent so this is validated, not used)
//   kv_group must be 1 (a single head_kv group is shared by all H heads)
//   out must not alias q, kv, indices, or lse (the two-pass softmax writes a
//       row into `out` then reads it back; a shared buffer corrupts the run)
//
// `lse` may be null when `return_lse` is false; otherwise it must be large
// enough for `S_q * H` fp32 values. The HIP kernel (dsa.hip) enforces the
// same preconditions at launch, converting a misconfigured caller into a
// named error instead of a silent hang (issue #57).
void dsa_sparse_fwd_cpu(int S_q, int S_kv, int H, int dim, int tail_dim,
                        int topk, int kv_group, int block_I, int inner_iter,
                        float sm_scale, bool return_lse,
                        const float* q, const float* kv,
                        const int32_t* indices, float* out, float* lse);

// Per-shape (decode vs prefill) launch tile selector. Writes the tile the
// HIP kernel should use:
//   decode  (S_q <= 8) : one query row per block, one wavefront (64 threads)
//   prefill (S_q >  8) : BQ query rows per block, 256 threads (4 wavefronts)
// `block_I` is the per-pass key tile (default 64); `inner_iter` repeats it so
// that `block_I * inner_iter` divides `topk` (default 1; raise it to trade
// register pressure for fewer passes on large topk).
void dsa_config_for(int S_q, int H, int dim, int topk, int* bq, int* threads,
                    int* block_I, int* inner_iter);

// ---------------------------------------------------------------------------
//  DSA paged-MQA gated top-k logits (issue #51, the kpool>1 indexer path).
//
//  The INDEXER computes, per query token and paged KV tile, a gated logit
//  that the subsequent top-k selects over (GLM-5.3-Flash `index_n_heads=32`,
//  `index_head_dim=128`, block_size=64 hardcoded in deep_gemm). The tilelang
//  kernel JIT-compiles on gfx942 but the launched kernel NEVER returns for
//  num_heads in {32,64}; deep_gemm.fp8_paged_mqa_logits is CUDA-only. This is
//  the portable replacement — the FIRST stage (kpool logits) that feeds the
//  PR #52 sparse-MLA forward.
//
//  Computation (per batch b, KV token t = i*block + j; i in
//  [0, ceildiv(seq_len[b], block)), j in [0, block)):
//
//    out[b, t] = k_scale[ page[b,i], j ]
//              * Sum_h ( max(0, Sum_d Q[b,h,d] * K[ page[b,i], j,d ] )
//                        * gate[b, h] )
//
//  Tokens t >= seq_len[b] are LEFT UNWRITTEN — exactly as the tilelang path
//  leaves them with `clean_logits=False` (the wrapper allocates with
//  `new_empty`, i.e. UNINITIALISED; sglang's `topk_from_pooled_history_logits`
//  masks invalid positions via `group_lengths`/`topk_offsets`/`seq_lens` BEFORE
//  the top-k, so unwritten/zero/garbage are all excluded). The HIP caller and
//  the unit test ZERO the output first (strictly safer than the original's
//  `new_empty`, harmless under the same masking).
//
//  Tensors (kv_group == 1; `page_size = block = 64`, `head_dim = 128`):
//
//    q        : [bs, H, D]         fp8 e4m3fnuz (device) / fp32 (oracle)
//    kv       : [num_blocks, block, D]                 fp8 e4m3fnuz / fp32
//    k_scale  : [num_blocks, block]                    fp32 (per-token
//               scale, packed in the trailing `block*4` bytes of each KV
//               block on the device path; passed separately on the CPU path)
//    gate     : [bs, H]                               fp32 (the indexer's
//               `_get_logits_head_gate` weight, after `.squeeze(2)`)
//    seq_lens : [bs]                                  int32 (the POOLED valid
//               KV count per batch — `pool_seqlens` in sglang)
//    page_table: [bs, max_table_len]                  int32 (the POOLED page
//               table — `pool_block_tables` in sglang; page_table[b,i] indexes
//               the `num_blocks` dim of kv/k_scale)
//    out      : [bs, max_seq_len]                     fp32
//               (max_seq_len = max_table_len * block; ZERO the output first)
//
//  `split_kv` is a PERFORMANCE knob only — the grouped logit is
//  grouping-independent (mirrors the forward's block_I/inner_iter), so any
//  positive split_kv yields the same top-k. The tilelang reference uses
//  `split_kv = max(1, min(max_seq_len // block, NUM_CU // batch_size))`
//  with `NUM_CU = 256` (MI300A); the HIP caller replicates this.
void dsa_topk_logits_cpu(int batch_size, int num_heads, int head_dim, int block,
                         int max_table_len, int num_blocks,
                         const float* q, const float* kv,
                         const float* k_scale, const float* gate,
                         const int32_t* seq_lens, const int32_t* page_table,
                         float* out);

// Whether an indexer shape fits gfx942's 64 KB NON-OPTIN dynamic-LDS cap
// under the fp32-Q kernel (dsa_topk_logits_kernel) -- the test the HIP
// launcher (dsa.hip::dsa_topk_logits) runs to pick the fast path. The
// kernel stages Q (H*D fp32), the per-head gate (H fp32), one K tile
// (B*D fp32) and its per-token scales (B fp32), so the request is
//
//   shmem = (H*D + H + B*D + B) * 4   bytes
//
// The GLM-5.3-Flash config (index_n_heads=32, index_head_dim=128,
// block=64) stages 49,536 B < 65,536 and is VERIFIED (see
// meta/benchmarks/test_dsa_topk_correct.hip). gfx942's opt-in ceiling
// EQUALS the non-optin cap (hipFuncSetAttribute(MaxDynamicSharedMemorySize,
// N>65536) returns hipSuccess but the launch silently never runs; verified
// on a CSCS beverin node -- see the KB note mi300a-dynamic-lds-no-optin), so
// doubling index_n_heads to 64 (66,048 B) CANNOT raise the cap. Instead the
// launcher dispatches dsa_topk_logits_kernel_fp8q (Q staged raw, dequantised
// on the fly -- bit-identical output), selected by dsa_topk_logits_fits_lds_fp8q
// below. Shapes fitting NEITHER variant are refused (a stderr diagnostic +
// no-op, leaving the caller's zeroed output to surface the (wrong, all-zero)
// top-k downstream) rather than silently launching a block the driver drops.
//
// Pure arithmetic on a documented device constant -- safe to call from host
// code, so the sglang backend can query it before launching and the host
// unit tests (tests/kernels/attn/test_dsa.cpp::DsaTopk::FitsLdsCap) assert
// on it.
bool dsa_topk_logits_fits_lds(int num_heads, int head_dim, int block);

// Whether an indexer shape fits gfx942's 64 KB non-optin dynamic-LDS cap
// under the fp8-Q kernel (dsa_topk_logits_kernel_fp8q) -- the launcher's
// FALLBACK for shapes dsa_topk_logits_fits_lds refuses. The fp8-Q kernel
// stages Q as RAW fp8 e4m3fnuz (1 byte/element, dequantised on the fly in
// the dot loop with the SAME fp8e4m3fnuz_to_f32 helper), and the gate (H),
// one K tile (B*D) and its per-token scales (B) as fp32, so the request is
//
//   shmem = (H + B*D + B) * 4 + H*D   bytes
//
// -- the fp32-Q request minus the 3*H*D bytes raw-fp8 Q saves. At the
// GLM-5.3 2x indexer (H=64, D=128, B=64) that is 41,472 B (vs the fp32-Q
// kernel's 66,048 B). The dequanted Q values, the fp32 accumulator and the
// written output are BIT-IDENTICAL to the fp32-Q kernel, so the H=32
// cross-check (max_rel < 1e-3) carries over. Pure arithmetic on the same
// device cap as dsa_topk_logits_fits_lds; host unit tests
// (tests/kernels/attn/test_dsa.cpp::DsaTopk::FitsLdsFp8q) assert on it.
bool dsa_topk_logits_fits_lds_fp8q(int num_heads, int head_dim, int block);

// Whether the indexer shape fits gfx942's 64 KB NON-OPTIN dynamic-LDS cap
// under the MFMA kernel (dsa_topk_logits_kernel_mfma) -- the launcher's
// FAST path, picked FIRST by dsa_topk_logits at every width it fits (the
// smallest-footprint variant; e.g. H=32 which the fp32-Q kernel ALSO fits).
// The kernel stages Q transposed as bf16 sQt[D][H] (loaded ONCE per block,
// reused across every page in the split -- fp8->bf16 is lossless, verified
// by meta/benchmarks/check_fp8_bf16_exact before this kernel existed), one
// bf16 K-tile sK[B][BK=64] (reloaded per K-tile per page), the per-head
// gate sGate[H] and the per-token scales sKscale[B] as fp32, so the request
// is
//
//   shmem = (D*H + B*BK)*2 + (H + B)*4   bytes   (BK = 64, fixed)
//
// -- the SMALLEST of the three variants at every GLM-5.3 indexer width:
// 16,768 B at H=32, 25,088 B at H=64, 41,728 B at H=128 (vs the fp8-Q
// kernel's 37,248 / 41,472 / 49,920 B and the fp32-Q kernel's
// 49,536 / 66,048 / 98,432 B). Shape constraints (the verified
// 16x16x16bf16_1k fragment needs exact multiples): num_heads % 16 == 0
// (kNF = H/16 column fragments), head_dim % 64 == 0 (BK=64 K-tiles) and
// block % 16 == 0 (BM = B, one wavefront per 16-row fragment). H not a
// multiple of 16 (e.g. 246) cannot use this kernel and is refused by the
// launcher exactly as before. Pure arithmetic on the same device cap as
// dsa_topk_logits_fits_lds; host unit tests
// (tests/kernels/attn/test_dsa.cpp::DsaTopk::FitsLdsMfma) assert on it.
bool dsa_topk_logits_fits_lds_mfma(int num_heads, int head_dim, int block);

// The optimal split_kv for the HIP dsa_topk_logits indexer (issue #51) --
// the single source of truth for the formula the hip_capi.hpp ABI
// docstring used to restate (with the wrong NUM_CU). The kernel's grid is
// (batch_size, split_kv); each split block loops over a ceildiv(max_seq_len,
// block)/split_kv slice of the page range, so split_kv is PERFECT ONLY
// (grouping-independent -- any positive value yields the same logits; see
// test_dsa_topk_correct.hip case split=2). The binding constraint at decode
// is occupancy (one wavefront per block on MI300A's 228 CUs), so more splits
// is strictly better until EITHER the page range is exhausted (one page per
// split) OR the grid saturates the CUs:
//
//   split_kv = max(1, min( ceildiv(max_seq_len, block), NUM_CU / batch_size ))
//
// with NUM_CU = 228 (MI300A / gfx942; hipDeviceProp_t::multiProcessorCount,
// verified on a CSCS beverin node). At bs=1, max_seq_len=4096, block=64 this
// is 64 (one page per split, 64 of 228 CUs used) -- measured 21.5 ms -> 0.36 ms
// (59.9x; meta/benchmarks/bench_dsa_topk.hip). At bs=64 the same shape is
// min(64, 228/64) = 3 (192 of 228 CUs).
//
// Pure arithmetic on a documented device constant -- safe to call from host
// code, so the sglang backend can call this before launching instead of
// hand-computing the split. Host unit tests: tests/kernels/attn/test_dsa.cpp
// ::DsaTopk::SplitFor. Raise NUM_CU here alongside the fp8-Q variant's cap
// (dsa_topk_logits_fits_lds_fp8q) + tiled-key/MFMA for devices with a
// different CU count.
int dsa_topk_logits_split_for(int batch_size, int max_seq_len, int block);

}  // namespace vkernels::kernels

#if VKERNELS_HAS_HIP
namespace vkernels::kernels::hip {

// HIP sparse-MLA forward (gfx942). Online softmax in fp32, bf16 storage,
// bf16-tolerant against the CPU oracle. `q`/`kv` are bf16 device pointers
// (`const __hip_bfloat16*`); `indices` is int32 device; `out` is bf16 device;
// `lse` is fp32 device (nullable when `return_lse` is false). Device pointers
// must reside in device or host-pinned memory. `tail_dim == 0` is handled by
// skipping the rope-tail dot at runtime (no zero-size GEMM).
void dsa_sparse_fwd(int S_q, int S_kv, int H, int dim, int tail_dim,
                    int topk, int kv_group, int block_I, int inner_iter,
                    float sm_scale, bool return_lse,
                    const void* q, const void* kv, const void* indices,
                    void* out, void* lse);

// Explicit-tile entry point (offline autotuner hook). Dispatches the concrete
// (bq, block_I, inner_iter) tile; threads is derived as max(bq,1)*64 capped
// at 256. `bn_kv` is reserved for a future tiled-key prefetch.
void dsa_sparse_fwd_with_tile(int S_q, int S_kv, int H, int dim, int tail_dim,
                              int topk, int kv_group, float sm_scale,
                              bool return_lse,
                              const void* q, const void* kv,
                              const void* indices, void* out, void* lse,
                              int bq, int block_I, int inner_iter, int bn_kv);

// DSA paged-MQA gated top-k logits (gfx942), issue #51. Same computation
// as dsa_topk_logits_cpu (see above for the formula and the left-unwritten
// contract), but the caller passes the FP8 e4m3fnuz Q/K raw and the device
// dequants on load (mirrors dsa_sparse_fwd's bf16->fp32). `head_dim` is
// fixed at 128 (no rope tail).
//
// `q_fp8`/`kvcache_u8` are fp8 e4m3fnuz device pointers; `kvcache_u8` is the
// `(num_blocks, block*(head_dim+4))` uint8 view (B*D fp8 keys, then B fp32
// per-token scales). `weight`/`seq_lens`/`page_table` are fp32/int32 device
// pointers; `out` is fp32 device (ZERO the output first).
//
// Dispatches on the staged-bytes cap (gfx942's 64 KB NON-OPTIN dynamic-LDS
// limit; NO hipFuncSetAttribute opt-in past it -- see dsa_topk_logits_fits_lds
// and the KB note mi300a-dynamic-lds-no-optin): shapes that fit the MFMA
// kernel (bf16 sQt[D][H] staged once, bf16 K-tile reloaded -- the SMALLEST
// variant; see dsa_topk_logits_fits_lds_mfma) take the fast path; shapes
// the MFMA kernel refuses but the fp32-Q kernel fits take that (the verified
// GLM-5.3 indexer H=32, D=128, B=64 -> 49,536 B); shapes fitting NEITHER but
// the fp8-Q kernel (Q staged raw, dequantised on the fly -- bit-identical
// output; see dsa_topk_logits_fits_lds_fp8q) take the fallback; shapes
// fitting NONE are refused (a stderr diagnostic + no-op, leaving `out` as
// the caller provided).
//
// `dsa_topk_logits_with_variant` (below) is the explicit-variant hook the
// autotuner/correctness harness use to FORCE a specific kernel (0=auto,
// 1=fp32q, 2=fp8q, 3=mfma) at a given shape, so every path stays exercised
// even when the auto dispatcher would pick a different one.
void dsa_topk_logits(int batch_size, int num_heads, int head_dim, int block,
                     int max_table_len, int max_seq_len, int split_kv,
                     const void* q_fp8, const void* kvcache_u8,
                     const void* weight, const void* seq_lens,
                     const void* page_table, void* out);

// Explicit-variant entry point (offline-autotuner / correctness hook).
// Runs a SPECIFIC kernel at the given shape, bypassing the auto dispatcher
// in dsa_topk_logits above:
//   variant 0 -> auto (mfma-if-fits, else fp32q-if-fits, else fp8q-if-fits,
//                      else refuse); identical to dsa_topk_logits
//   variant 1 -> dsa_topk_logits_kernel        (fp32-Q)
//   variant 2 -> dsa_topk_logits_kernel_fp8q    (fp8-Q)
//   variant 3 -> dsa_topk_logits_kernel_mfma    (bf16 MFMA)
// An explicit variant (1/2/3) that does NOT fit the shape's LDS cap is
// refused with a stderr diagnostic + no-op (the caller zeroed `out`, which
// is what stays) rather than launch a block gfx942's driver would drop --
// mirrors dsa_topk_logits's contract. Same pointers/contract as
// dsa_topk_logits.
void dsa_topk_logits_with_variant(int batch_size, int num_heads, int head_dim,
                                  int block, int max_table_len,
                                  int max_seq_len, int split_kv,
                                  const void* q_fp8, const void* kvcache_u8,
                                  const void* weight, const void* seq_lens,
                                  const void* page_table, void* out,
                                  int variant);

}  // namespace vkernels::kernels::hip
#endif  // VKERNELS_HAS_HIP

// meta/benchmarks/test_dsa_topk_correct.hip
//
// End-to-end correctness test for the DSA paged-MQA gated top-k logits
// (issue #51) on gfx942, against the CPU reference in
// vkernels::kernels::dsa_topk_logits_cpu.
//
//   hip::dsa_topk_logits  vs  dsa_topk_logits_cpu (the gated-logit oracle)
//
// GLM-5.3-Flash indexer (index_n_heads=32, head_dim=128, block=64) at
// batch in {1, 2} and max_table_len in {8, 16} (max_seq_len in {512, 1024}),
// plus smaller sanity shapes. seq_lens are truncated on a couple of cases to
// exercise the t < seq_len write guard, and split_kv=2 on one case to verify
// the grid's perf-only slicing is actually grouping-independent.
//
// Method. The source Q and K are torch.float8_e4m3fnuz (raw uint8). The
// harness generates fp8 bytes directly, then BOTH paths dequant them via the
// SAME helper (fp8e4m3fnuz_to_f32 in moe_device.hip -- __host__ __device__,
// copied verbatim into the anonymous namespace below): the CPU oracle runs on
// the host-dequanted fp32, the device kernel dequants on load. With identical
// dequant, the only residual is FMA vs IEEE mul+add over the D-dot and H-sum
// (a few ULP), so we require max_rel < 1e-3.
//
// Invariant (the caller contract the kernel relies on): page_table[b,i] is
// VALID (in [0, num_blocks)) for every used slot i < ceildiv(seq_len, B).
// Unused slots (i >= ceildiv(seq_len, B)) are never read. The harness only
// generates valid pages in used slots; the CPU oracle ADDITIONALLY masks OOB
// pages (defensive, verified by tests/kernels/attn/test_dsa.cpp::
// DsaTopk::OutOfBoundPageIsUnwritten), but the kernel has no such guard -- it
// relies on sglang's invariant, so the harness must respect it.
//
// NOTE: the GLM-5.3 config (H=32, D=128, B=64) stages 49.5 KB < gfx942's
// 64 KB non-optin LDS cap (its opt-in ceiling EQUALS the non-optin cap -- no
// hipFuncSetAttribute opt-in past 64 KB, verified on a CSCS beverin node;
// see the KB note mi300a-dynamic-lds-no-optin), so the launcher's fp32-Q
// fast path runs it. H=64 (66 KB) and H=128 (99 KB) exceed the fp32-Q cap,
// so the launcher dispatches the fp8-Q variant (Q staged raw, dequantised on
// the fly -- bit-identical output, same cross-check below) and BOTH are
// exercised here alongside the H=32 headline (the index_n_heads GLM-5.3
// actually uses, which works where the tilelang path hangs).

#include <hip/hip_runtime.h>

#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <vector>

#include "vkernels/kernels/dsa.hpp"

#define CK(e, m)                                                       \
  do {                                                                 \
    hipError_t r = (e);                                                \
    if (r != hipSuccess) {                                             \
      std::fprintf(stderr, "%s: %s\n", m, hipGetErrorString(r));       \
      std::exit(1);                                                    \
    }                                                                  \
  } while (0)

namespace {

float rnd(int seed, int i) {  // deterministic pseudo-random in [-1, 1]
  unsigned x = (unsigned)(seed * 2654435761u + (unsigned)i * 40503u);
  x ^= x >> 13;
  x *= 0x5bd1e995u;
  x ^= x >> 15;
  return (float)((int)x % 200000) / 100000.0f;
}

// fp8 e4m3fnuz byte in [0,254] excluding 0x7F (+NaN) and 0xFF (-NaN) --
// mirrors real KV cache data (no NaNs; 0x00 and 0x80 both decode to +0).
uint8_t rnd_fp8(int seed, int i) {
  unsigned x = (unsigned)(seed * 2654435761u + (unsigned)i * 40503u);
  x ^= x >> 13;
  x *= 0x5bd1e995u;
  x ^= x >> 15;
  uint8_t b = (uint8_t)(x % 255u);   // 0..254 (excludes 0xFF)
  if (b == 0x7Fu) b = 0u;            // exclude +NaN; 0x00 is +0 (fine)
  return b;
}

// fp8 e4m3fnuz -> fp32. VERBATIM copy of fp8e4m3fnuz_to_f32 in
// moe_device.hip (__host__ __device__); the harness dequants on the host,
// the device kernel dequants on load via its own copy. Both MUST agree --
// the kernel's docstring asserts this, and we cross-check it here.
__host__ __device__ __forceinline__ float fp8e4m3fnuz_to_f32(uint8_t b) {
  const uint32_t s = static_cast<uint32_t>(b >> 7) & 1u;     // sign
  const uint32_t e = static_cast<uint32_t>(b >> 3) & 0xFu;   // exponent (bias 8)
  const uint32_t m = static_cast<uint32_t>(b) & 0x7u;        // mantissa (3)
  if ((b & 0x7Fu) == 0u) return 0.0f;                        // +0 (0x00 AND 0x80)
  float f;
  if (e == 15u && m == 7u) {                                 // 0x7F = NaN -> qNaN
    const uint32_t qnan = 0x7fc00000u;
    __builtin_memcpy(&f, &qnan, sizeof(f));
  } else if (e == 0u) {                                      // subnormal: m*2^-7
    const float v = static_cast<float>(m) * 0x1p-7f;         // m*2^(1-8), exact
    f = s ? -v : v;
  } else {                                                   // normal: 2^(e-8)*(1+m/8)
    const uint32_t bits = (s << 31) | ((e + 119u) << 23) | (m << 20);
    __builtin_memcpy(&f, &bits, sizeof(f));
  }
  return f;
}

struct Stats { double max_abs, max_rel; };

void cmp_out(const std::vector<float>& got, const std::vector<float>& ref,
             Stats* s) {
  for (size_t i = 0; i < ref.size(); ++i) {
    double e = std::fabs((double)got[i] - ref[i]);
    if (e > s->max_abs) s->max_abs = e;
    double d = std::fmax(std::fabs((double)ref[i]), 1.0);
    if (e / d > s->max_rel) s->max_rel = e / d;
  }
}

}  // namespace

int main() {
  hipDeviceProp_t p;
  CK(hipGetDeviceProperties(&p, 0), "props");
  std::printf("GPU: %s (arch=%s)\n", p.name, p.gcnArchName);

  // Peak buffers across all cases (Hmax=128 covers the 4x indexer fp8-Q path).
  const int Bmax = 64, Hmax = 128, Dmax = 128;
  const int MTmax = 16, NBmax = 16, BSmax = 2;
  const int MSMmax = MTmax * Bmax;  // 1024
  uint8_t *dq, *dkv, *dout;
  int32_t *dsl, *dpt;
  float *dw;
  CK(hipMalloc(&dq, (size_t)BSmax * Hmax * Dmax), "alloc q");
  CK(hipMalloc(&dkv, (size_t)NBmax * Bmax * (Dmax + 4)), "alloc kv");
  CK(hipMalloc(&dw, (size_t)BSmax * Hmax * 4), "alloc weight");
  CK(hipMalloc(&dsl, (size_t)BSmax * 4), "alloc seq_lens");
  CK(hipMalloc(&dpt, (size_t)BSmax * MTmax * 4), "alloc page_table");
  CK(hipMalloc(&dout, (size_t)BSmax * MSMmax * 4), "alloc out");

  int fails = 0;
  const float OUT_THRESH = 1e-3f;

  struct Cfg { int bs, H, D, B, mt, nb, split_kv, variant; };
  const Cfg cfgs[] = {
      {1, 32, 128, 64, 8, 8, 1, 0},    // GLM-5.3 indexer decode (auto->mfma)
      {1, 32, 128, 64, 16, 16, 1, 0},  // more pages (max_seq_len=1024)
      {2, 32, 128, 64, 8, 8, 1, 0},    // batch > 1
      {1, 32, 128, 64, 8, 8, 2, 0},    // split_kv=2 (perf-only; must match)
      {1, 64, 128, 64, 8, 8, 1, 0},    // GLM-5.3 2x indexer (auto->mfma, 512)
      {1, 64, 128, 64, 16, 16, 1, 0},  // 2x indexer, more pages (1024)
      {2, 64, 128, 64, 8, 8, 1, 0},    // 2x indexer, batch > 1
      {1, 64, 128, 64, 8, 8, 2, 0},    // 2x indexer, split_kv=2 (must match)
      {1, 128, 128, 64, 8, 8, 1, 0},   // 4x indexer (auto->mfma, 41,728 B)
      {1, 4, 16, 8, 32, 32, 1, 0},     // smaller D, sanity (auto->fp32-Q)
      {1, 2, 8, 4, 16, 16, 1, 0},      // small (auto->fp32-Q)
      {1, 1, 2, 2, 4, 4, 1, 0},        // tiny hand-check (auto->fp32-Q)
      // --- FORCE each kernel at the GLM-5.3 shape (H=32 fits ALL three) ---
      // so every path stays exercised even if the auto dispatcher would pick
      // a different one. Cross-checked against the SAME oracle below.
      {1, 32, 128, 64, 8, 8, 1, 1},    // force fp32-Q
      {1, 32, 128, 64, 8, 8, 1, 2},    // force fp8-Q
      {1, 32, 128, 64, 8, 8, 1, 3},    // force mfma
  };

  int ci = 0;
  for (const auto& c : cfgs) {
    const int max_seq_len = c.mt * c.B;
    const size_t nq = (size_t)c.bs * c.H * c.D;
    const size_t nkvbytes = (size_t)c.nb * c.B * (c.D + 4);
    const size_t nw = (size_t)c.bs * c.H;
    const size_t nout = (size_t)c.bs * max_seq_len;

    std::vector<uint8_t> q_u8(nq), kv_u8(nkvbytes);
    std::vector<float> q_f32(nq), kv_f32((size_t)c.nb * c.B * c.D);
    std::vector<float> k_scale((size_t)c.nb * c.B);
    std::vector<float> weight(nw);
    std::vector<int32_t> sl(c.bs);
    std::vector<int32_t> pt((size_t)c.bs * c.mt);

    // Q: raw fp8 bytes + host dequant (both paths see the same value).
    for (size_t i = 0; i < nq; ++i) {
      q_u8[i] = rnd_fp8(1, (int)i);
      q_f32[i] = fp8e4m3fnuz_to_f32(q_u8[i]);
    }
    // k_scale: fp32 in [0.75, 1.25] (packed in the trailing B*4 bytes/block).
    for (size_t i = 0; i < k_scale.size(); ++i)
      k_scale[i] = static_cast<float>(rnd(3, (int)i)) * 0.25f + 1.0f;
    // kvcache_u8 [nb, B*(D+4)]: per block, B*D fp8 keys then B fp32 scales.
    const size_t kvstride = (size_t)c.B * (c.D + 4);
    for (int p = 0; p < c.nb; ++p) {
      uint8_t* bp = kv_u8.data() + (size_t)p * kvstride;
      for (int j = 0; j < c.B; ++j)
        for (int d = 0; d < c.D; ++d)
          bp[(size_t)j * c.D + d] = rnd_fp8(2 + p, j * c.D + d);
      std::memcpy(bp + (size_t)c.B * c.D, k_scale.data() + (size_t)p * c.B,
                  (size_t)c.B * sizeof(float));
    }
    // Host-dequanted keys for the CPU oracle ([nb, B, D] fp32).
    for (int p = 0; p < c.nb; ++p)
      for (int j = 0; j < c.B; ++j)
        for (int d = 0; d < c.D; ++d)
          kv_f32[((size_t)p * c.B + j) * c.D + d] =
              fp8e4m3fnuz_to_f32(kv_u8[(size_t)p * kvstride + (size_t)j * c.D + d]);
    // gate (weight) in [-1, 1].
    for (size_t i = 0; i < nw; ++i) weight[i] = rnd(4, (int)i);
    // seq_lens: mostly full; truncate the first batch of every third config
    // (ci 0,3,6) to exercise the t < seq_len write guard.
    for (int b = 0; b < c.bs; ++b)
      sl[b] = (ci % 3 == 0 && b == 0) ? max_seq_len * 3 / 4 : max_seq_len;
    // page_table: VALID pages in used slots (i < ceildiv(seq_len,B));
    // unused slots (i >= that) are never read -> fill 0.
    for (int b = 0; b < c.bs; ++b) {
      const int np_total = (sl[b] + c.B - 1) / c.B;
      for (int i = 0; i < c.mt; ++i)
        pt[(size_t)b * c.mt + i] =
            (i < np_total) ? (int32_t)(((unsigned)(b * 7 + i * 13)) %
                                        (unsigned)c.nb)
                           : 0;
    }

    // CPU oracle on the host-dequanted fp32 (output zeroed first).
    std::vector<float> ref(nout, 0.0f);
    vkernels::kernels::dsa_topk_logits_cpu(
        c.bs, c.H, c.D, c.B, c.mt, c.nb, q_f32.data(), kv_f32.data(),
        k_scale.data(), weight.data(), sl.data(), pt.data(), ref.data());

    // Device.
    CK(hipMemcpy(dq, q_u8.data(), nq, hipMemcpyHostToDevice), "cpyq");
    CK(hipMemcpy(dkv, kv_u8.data(), nkvbytes, hipMemcpyHostToDevice), "cpykv");
    CK(hipMemcpy(dw, weight.data(), nw * 4, hipMemcpyHostToDevice), "cpyw");
    CK(hipMemcpy(dsl, sl.data(), (size_t)c.bs * 4, hipMemcpyHostToDevice), "cpysl");
    CK(hipMemcpy(dpt, pt.data(), (size_t)c.bs * c.mt * 4, hipMemcpyHostToDevice), "cpypt");
    CK(hipMemset(dout, 0, nout * sizeof(float)), "zero out");
    vkernels::kernels::hip::dsa_topk_logits_with_variant(
        c.bs, c.H, c.D, c.B, c.mt, max_seq_len, c.split_kv, dq, dkv, dw, dsl,
        dpt, dout, c.variant);
    CK(hipDeviceSynchronize(), "sync");

    std::vector<float> got(nout);
    CK(hipMemcpy(got.data(), dout, nout * 4, hipMemcpyDeviceToHost), "rdout");

    Stats st{};
    cmp_out(got, ref, &st);
    bool ok = st.max_rel < OUT_THRESH;
    const char* vn = c.variant == 0 ? "auto" : c.variant == 1 ? "fp32"
                       : c.variant == 2 ? "fp8q" : "mfma";
    std::printf("  bs=%-2d H=%-2d D=%-3d B=%-2d mt=%-2d nb=%-2d split=%d v=%-4s "
                "out[a=%.4f r=%.6f]  %s\n",
                c.bs, c.H, c.D, c.B, c.mt, c.nb, c.split_kv, vn, st.max_abs,
                st.max_rel, ok ? "PASS" : "FAIL");
    if (!ok) ++fails;
    ++ci;
  }

  hipFree(dq); hipFree(dkv); hipFree(dw); hipFree(dsl); hipFree(dpt); hipFree(dout);
  std::printf("\n%s (%d failure(s))\n", fails ? "FAIL" : "PASS", fails);
  return fails ? 1 : 0;
}

// meta/benchmarks/bench_dsa_topk.hip
//
// Micro-benchmark for the DSA paged-MQA gated top-k logits (issue #51) on
// AMD gfx942 (MI300A). This is the INDEXER stage that feeds
// hip::dsa_sparse_fwd: each query scores its paged KV tiles and the
// integrator's top-k then selects the blocks to attend over.
//
//   out[b, t] = k_scale[page[b,i], j] *
//               sum_h ( max(0, sum_d Q[b,h,d] * K[page[b,i],j,d] )
//                                  * gate[b,h] )
//   where t = i*block + j, t < seq_lens[b] (else left unwritten).
//
// The kernel is a scalar GEMV baseline (one wavefront per
// (batch, split_kv) block, one lane per KV token, sequential H-sum, K
// staged once per page in fp32 and reused across all H heads -- no MFMA,
// no tiled-key prefetch). At decode (bs=1, split=1) the grid is ONE
// wavefront (one of MI300A's 228 CUs), so the binding constraint is
// OCCUPANCY, not HBM bandwidth: the working set (68-560 KB for these
// shapes) is L2-resident after warmup. The headline number is therefore
// decode latency, and the split_kv sweep (perf-only, grouping-
// independent) shows near-linear speedup as the page range is spread
// across more CUs. A roofline AI is still printed but the "mem" label
// is the HBM-side classification -- in cache it is single-wavefront
// latency that bounds this baseline, and the tiled-key/MFMA follow-on
// is what raises occupancy AND moves toward the compute roof.
//
// Reported per shape, against the MI300A roof (gfx942: ~1307 TFLOP/s bf16
// Matrix-Core, ~5300 GB/s HBM3, ridge ~247 FLOP/byte):
//   * median / min latency (us) -- the headline at decode,
//   * FLOP/s        = bs * max_seq_len * (2*D*H + 2*H + 1) / t,
//   * effective GB/s = working-set bytes / t (L2-resident after warmup;
//                      NOT a meaningful % of the HBM roof at these sizes),
//   * arithmetic intensity and the HBM-side roofline label (mem/comp).
//
// Shapes: GLM-5.3-Flash indexer (index_n_heads=32, index_head_dim=128,
// block=64) at decode (bs=1) sweeping max_table_len in {8,16,32,64} ->
// max_seq_len in {512,1024,2048,4096}; batch scaling bs in {2..64}; a
// split_kv sweep on the largest decode (perf-only, grouping-independent);
// and two small sanity shapes.
//
// Built only with VKERNELS_HAS_HIP + VKERNELS_BUILD_BENCHMARKS.

#include <hip/hip_runtime.h>

#include <algorithm>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <functional>
#include <vector>

#include "vkernels/kernels/dsa.hpp"

static void check_hip(hipError_t err, const char* ctx) {
  if (err != hipSuccess) {
    std::fprintf(stderr, "HIP error (%s): %s\n", ctx, hipGetErrorString(err));
    std::exit(1);
  }
}

struct GpuInfo { std::string name; int arch; int cus; double tflops, bw; };
static GpuInfo get_gpu_info() {
  hipDeviceProp_t p;
  check_hip(hipGetDeviceProperties(&p, 0), "props");
  GpuInfo i;
  i.name = p.name;
  i.cus = p.multiProcessorCount;   // MI300A gfx942 = 228 CUs
  if (std::strstr(p.gcnArchName, "gfx942"))      { i.arch = 942; i.tflops = 1307; i.bw = 5300; }
  else if (std::strstr(p.gcnArchName, "gfx90a")) { i.arch = 90;  i.tflops = 383;  i.bw = 3200; }
  else                                            { i.arch = 0;   i.tflops = 100;  i.bw = 1000; }
  return i;
}

struct BenchResult { double min_us, median_us, mean_us; double cv; };

// Variance-driven iteration count: warmup, then keep doubling iters until
// std/mean < 3% (or hit the cap). Times each launch with HIP events
// (NOT host steady_clock, which would measure launch+sync overhead).
// MI300A dynamic sclk (no opt-in lock here) scales DOWN between configs
// during the host-side setup (hipFree/malloc/memcpy), and hipEventElapsedTime
// then returns a corrupted 0 across the clock-domain change. We prevent it
// by warming up generously AND syncing AFTER the warmup (so the sclk is
// high+stable before the first timed event), and fall back to a launch
// burst + re-measure (up to twice) if a converged median is still
// implausibly small -- any kernel here is >= ~190 us (bs=1,mt=2).
static BenchResult bench_us(const std::function<void()>& launch,
                            hipEvent_t start, hipEvent_t stop,
                            int warmup = 50, int max_iters = 1000) {
  constexpr float kImplausibleUs = 1.0f;

  auto measure_once = [&] {
    (void)hipDeviceSynchronize();
    for (int i = 0; i < warmup; ++i) launch();
    (void)hipDeviceSynchronize();   // wait out the warmup: sclk high+stable
    std::vector<float> times;
    int iters = 20;
    while (iters <= max_iters) {
      times.clear();
      for (int i = 0; i < iters; ++i) {
        (void)hipEventRecord(start);
        launch();
        (void)hipEventRecord(stop);
        (void)hipEventSynchronize(stop);
        float ms = 0;
        (void)hipEventElapsedTime(&ms, start, stop);
        times.push_back(ms * 1000.0f);
      }
      double sum = 0;
      for (double t : times) sum += t;
      double mean = sum / iters;
      double sum2 = 0;
      for (double t : times) sum2 += t * t;
      double var = sum2 / iters - mean * mean;
      double stddev = std::sqrt(std::max(0.0, var));
      double cv = mean > 0 ? stddev / mean : 0;
      if (cv < 0.03 || iters >= max_iters) {
        std::sort(times.begin(), times.end());
        return BenchResult{times[0], times[iters / 2], mean, cv};
      }
      iters *= 2;
    }
    return BenchResult{};
  };

  auto r = measure_once();
  for (int attempt = 0; attempt < 2 && r.median_us <= kImplausibleUs;
       ++attempt) {
    // sclk scaled down mid-measurement: push it back up with a long
    // launch burst, then re-measure.
    (void)hipDeviceSynchronize();
    for (int i = 0; i < 256; ++i) launch();
    (void)hipDeviceSynchronize();
    r = measure_once();
  }
  return r;
}

// fp8 e4m3fnuz byte in [0,254] excluding 0x7F (+NaN) and 0xFF (-NaN) --
// representative KV-cache data (no NaNs; 0x00 and 0x80 both decode to +0).
static uint8_t rnd_fp8(int seed, int i) {
  unsigned x = (unsigned)(seed * 2654435761u + (unsigned)i * 40503u);
  x ^= x >> 13;
  x *= 0x5bd1e995u;
  x ^= x >> 15;
  uint8_t b = (uint8_t)(x % 255u);   // 0..254 (excludes 0xFF)
  if (b == 0x7Fu) b = 0u;            // exclude +NaN; 0x00 is +0 (fine)
  return b;
}

static float rnd(int seed, int i) {  // deterministic pseudo-random in [-1, 1)
  unsigned x = (unsigned)(seed * 2654435761u + (unsigned)i * 40503u);
  x ^= x >> 13; x *= 0x5bd1e995u; x ^= x >> 15;
  return (float)((int)x % 200000) / 100000.0f - 1.0f;
}

// ---------------------------------------------------------------------------
// Build kvcache_u8 [nb, B*(D+4)] for the kernel: per block, B*D fp8 keys
// then B fp32 per-token scales (the [0.75, 1.25] gate scales). Mirrors
// test_dsa_topk_correct.hip exactly.
static void build_kvcache(std::vector<uint8_t>& kv, std::vector<float>& ks,
                          int nb, int B, int D) {
  const size_t kvstride = (size_t)B * (D + 4);
  kv.assign((size_t)nb * kvstride, 0);
  ks.assign((size_t)nb * B, 0.0f);
  for (size_t i = 0; i < ks.size(); ++i)
    ks[i] = rnd(3, (int)i) * 0.25f + 1.0f;   // [0.75, 1.25]
  for (int p = 0; p < nb; ++p) {
    uint8_t* bp = kv.data() + (size_t)p * kvstride;
    for (int j = 0; j < B; ++j)
      for (int d = 0; d < D; ++d)
        bp[(size_t)j * D + d] = rnd_fp8(2 + p, j * D + d);
    std::memcpy(bp + (size_t)B * D, ks.data() + (size_t)p * B,
                (size_t)B * sizeof(float));
  }
}

// ---------------------------------------------------------------------------
// GLM-5.3 indexer sweep (index_n_heads=32, index_head_dim=128, block=64).
static void bench_indexer(const GpuInfo& info, hipEvent_t start,
                          hipEvent_t stop) {
  struct Cfg { int bs, H, D, B, mt, nb, split; };
  const Cfg cfgs[] = {
      // --- GLM-5.3 decode, max_table_len sweep (max_seq_len = mt*B) ---
      {1, 32, 128, 64,  8,  8, 1},    // decode,  512 tokens
      {1, 32, 128, 64, 16, 16, 1},    // decode, 1024 tokens
      {1, 32, 128, 64, 32, 32, 1},    // decode, 2048 tokens
      {1, 32, 128, 64, 64, 64, 1},    // decode, 4096 tokens
      // --- batch scaling (mt=8, decode-like until bs>1 fills the grid) ---
      {2, 32, 128, 64,  8,  8, 1},
      {4, 32, 128, 64,  8,  8, 1},
      {8, 32, 128, 64,  8,  8, 1},
      {16,32, 128, 64,  8,  8, 1},
      {32,32, 128, 64,  8,  8, 1},
      {64,32, 128, 64,  8,  8, 1},
      // --- GLM-5.3 2x indexer (H=64 -> fp8-Q fallback path) ---
      {1, 64, 128, 64,  8,  8, 1},    // decode,  512 tokens (fp8-Q)
      {1, 64, 128, 64, 16, 16, 1},    // decode, 1024 tokens (fp8-Q)
      {1, 64, 128, 64, 64, 64, 1},    // decode, 4096 tokens (fp8-Q)
      // --- short context (bs=1, mt=2): the latency floor at decode ---
      {1, 32,  128, 64,  2,  2, 1},
  };

  std::printf("\n=== hip::dsa_topk_logits (GLM-5.3 indexer) ===\n");
  std::printf("  %4s %4s %5s %4s %4s %4s %6s %9s %9s %9s %5s %4s  %s\n",
              "bs", "H", "ms_len", "B", "mt", "nb",
              "split", "us(min)", "us(med)", "GB/s", "AI", "%bw", "bound");

  for (const auto& c : cfgs) {
    const int bs = c.bs, H = c.H, D = c.D, B = c.B;
    const int mt = c.mt, nb = c.nb, split = c.split;
    const int max_seq_len = mt * B;

    const size_t nq = (size_t)bs * H * D;
    const size_t nkvbytes = (size_t)nb * B * (D + 4);
    const size_t nw = (size_t)bs * H;
    const size_t nout = (size_t)bs * max_seq_len;

    std::vector<uint8_t> q_u8(nq);
    std::vector<float> weight(nw);
    std::vector<int32_t> sl(bs);
    std::vector<int32_t> pt((size_t)bs * mt);
    std::vector<uint8_t> kv_u8;
    std::vector<float> k_scale;   // unused at launch (packed in kv)
    build_kvcache(kv_u8, k_scale, nb, B, D);
    for (size_t i = 0; i < nq; ++i) q_u8[i] = rnd_fp8(1, (int)i);
    for (size_t i = 0; i < nw; ++i) weight[i] = rnd(4, (int)i);
    for (int b = 0; b < bs; ++b) sl[b] = max_seq_len;   // full (no truncation)
    for (int b = 0; b < bs; ++b)
      for (int i = 0; i < mt; ++i)
        pt[(size_t)b * mt + i] = (int32_t)(((unsigned)(b * 7 + i * 13)) %
                                           (unsigned)nb);

    uint8_t *dq, *dkv, *dout;
    float *dw;
    int32_t *dsl, *dpt;
    check_hip(hipMalloc(&dq,   nq), "q");
    check_hip(hipMalloc(&dkv,  nkvbytes), "kv");
    check_hip(hipMalloc(&dw,   nw * 4), "w");
    check_hip(hipMalloc(&dsl,  (size_t)bs * 4), "sl");
    check_hip(hipMalloc(&dpt,  (size_t)bs * mt * 4), "pt");
    check_hip(hipMalloc(&dout, nout * 4), "out");
    check_hip(hipMemcpy(dq,   q_u8.data(),  nq, hipMemcpyHostToDevice), "cpyq");
    check_hip(hipMemcpy(dkv,  kv_u8.data(), nkvbytes, hipMemcpyHostToDevice),
              "cpykv");
    check_hip(hipMemcpy(dw,   weight.data(), nw * 4, hipMemcpyHostToDevice),
              "cpyw");
    check_hip(hipMemcpy(dsl,  sl.data(), (size_t)bs * 4, hipMemcpyHostToDevice),
              "cpysl");
    check_hip(hipMemcpy(dpt,  pt.data(), (size_t)bs * mt * 4,
              hipMemcpyHostToDevice), "cpypt");
    check_hip(hipMemset(dout, 0, nout * sizeof(float)), "zero out");

    auto L = [&] {
      vkernels::kernels::hip::dsa_topk_logits(
          bs, H, D, B, mt, max_seq_len, split, dq, dkv, dw, dsl, dpt, dout);
    };
    auto r = bench_us(L, start, stop);

    // FLOPs: per token, 2*D*H (the D-dot over H heads) + 2*H + 1
    //        (gate mul + H-sum + k_scale mul); the 2*D*H term dominates.
    double flops = (double)bs * max_seq_len *
                   (2.0 * D * H + 2.0 * H + 1.0);
    // Actual HBM: q read once (fp8), kv read once per referenced page
    // (fp8 keys + fp32 scales), weight read once (fp32), seq_lens + page_table
    // read once (int32), out written once (fp32). split_kv re-reads its
    // slice's pages per block -- counted in the kv term (each (b,i) page
    // is read by exactly one split block; the grid is grouping-independent).
    double bytes = (double)bs * H * D               // q (fp8)
                 + (double)bs * mt * B * (D + 4)    // kv (fp8 keys + fp32 ks)
                 + (double)bs * H * 4               // weight (fp32)
                 + (double)bs * 4                   // seq_lens (int32)
                 + (double)bs * mt * 4              // page_table (int32)
                 + (double)bs * max_seq_len * 4;    // out (fp32)
    double s = r.median_us / 1e6;
    double gbs = bytes / s / 1e9;
    double tflops = flops / s / 1e12;
    double ai = flops / bytes;
    double ridge = info.tflops * 1e3 / info.bw;   // FLOP/byte
    const char* bound = ai < ridge ? "mem" : "comp";
    double pct_bw = gbs / info.bw * 100.0;
    (void)tflops;
    std::printf("  %4d %4d %7d %4d %4d %4d %6d %9.1f %9.1f %9.1f %5.1f %4.1f"
                "  %s\n",
                bs, H, max_seq_len, B, mt, nb, split, r.min_us, r.median_us,
                gbs, ai, pct_bw, bound);

    check_hip(hipFree(dq), "fq");
    check_hip(hipFree(dkv), "fkv");
    check_hip(hipFree(dw), "fw");
    check_hip(hipFree(dsl), "fsl");
    check_hip(hipFree(dpt), "fpt");
    check_hip(hipFree(dout), "fout");
  }
  std::printf("  Roof: %.0f TFLOP/s bf16 (Matrix-Core), %.0f GB/s HBM3.\n"
              "  NB: the working set (68-560 KB for these shapes) is L2-resident\n"
              "      after warmup, so the kernel is NOT HBM-bandwidth-bound -- the\n"
              "      binding constraint at decode (bs=1, split=1) is OCCUPANCY: the\n"
              "      grid is ONE wavefront (one of MI300A's 228 CUs). split_kv\n"
              "      (below) distributes the page range across more CUs and gives\n"
              "      near-linear speedup; batch scaling is free parallelism up to\n"
              "      ~228 batches. The follow-on tiled-key/MFMA the kernel's\n"
              "      docstring references raises occupancy AND moves toward the\n"
              "      compute roof.\n",
              info.tflops, info.bw);
}

// ---------------------------------------------------------------------------
// split_kv sweep on the largest decode shape: perf-only, grouping-
// independent. Prints median-us per split so the caller can see whether
// more parallelism (more blocks across the page range) helps at a size
// where a single block may under-fill the GPU.
static void bench_split(const GpuInfo& info, hipEvent_t start, hipEvent_t stop) {
  const int bs = 1, H = 32, D = 128, B = 64, mt = 64, nb = 64;
  const int max_seq_len = mt * B;   // 4096
  const size_t nq = (size_t)bs * H * D;
  const size_t nkvbytes = (size_t)nb * B * (D + 4);
  const size_t nw = (size_t)bs * H;
  const size_t nout = (size_t)bs * max_seq_len;

  std::vector<uint8_t> q_u8(nq), kv_u8;
  std::vector<float> weight(nw), k_scale;
  std::vector<int32_t> sl(bs), pt((size_t)bs * mt);
  build_kvcache(kv_u8, k_scale, nb, B, D);
  for (size_t i = 0; i < nq; ++i) q_u8[i] = rnd_fp8(1, (int)i);
  for (size_t i = 0; i < nw; ++i) weight[i] = rnd(4, (int)i);
  for (int b = 0; b < bs; ++b) sl[b] = max_seq_len;
  for (int b = 0; b < bs; ++b)
    for (int i = 0; i < mt; ++i)
      pt[(size_t)b * mt + i] = (int32_t)(((unsigned)(b * 7 + i * 13)) %
                                         (unsigned)nb);

  uint8_t *dq, *dkv, *dout;
  float *dw;
  int32_t *dsl, *dpt;
  check_hip(hipMalloc(&dq,   nq), "q");
  check_hip(hipMalloc(&dkv,  nkvbytes), "kv");
  check_hip(hipMalloc(&dw,   nw * 4), "w");
  check_hip(hipMalloc(&dsl,  (size_t)bs * 4), "sl");
  check_hip(hipMalloc(&dpt,  (size_t)bs * mt * 4), "pt");
  check_hip(hipMalloc(&dout, nout * 4), "out");
  check_hip(hipMemcpy(dq,   q_u8.data(),  nq, hipMemcpyHostToDevice), "cpyq");
  check_hip(hipMemcpy(dkv,  kv_u8.data(), nkvbytes, hipMemcpyHostToDevice),
            "cpykv");
  check_hip(hipMemcpy(dw,   weight.data(), nw * 4, hipMemcpyHostToDevice),
            "cpyw");
  check_hip(hipMemcpy(dsl,  sl.data(), (size_t)bs * 4, hipMemcpyHostToDevice),
            "cpysl");
  check_hip(hipMemcpy(dpt,  pt.data(), (size_t)bs * mt * 4,
            hipMemcpyHostToDevice), "cpypt");

  std::printf("\n=== split_kv sweep (bs=%d H=%d D=%d B=%d mt=%d nb=%d,"
              " max_seq_len=%d, %d CUs) ===\n",
              bs, H, D, B, mt, nb, max_seq_len, info.cus);
  int rec = vkernels::kernels::dsa_topk_logits_split_for(bs, max_seq_len, B);
  std::printf("  dsa_topk_logits_split_for(%d, %d, %d) = %d  (recommended)\n",
              bs, max_seq_len, B, rec);
  std::printf("  %6s %9s %9s %9s %9s\n", "split", "us(min)", "us(med)",
              "GB/s", "speedup");
  double bytes = (double)bs * H * D + (double)bs * mt * B * (D + 4) +
                 (double)bs * H * 4 + (double)bs * 4 + (double)bs * mt * 4 +
                 (double)bs * max_seq_len * 4;
  const int splits[] = {1, 2, 4, 8, 16, 32, 64};   // 64 = ceildiv(4096, B)
  double base_us = -1;
  for (int sp : splits) {
    check_hip(hipMemset(dout, 0, nout * sizeof(float)), "zero out");
    auto L = [&] {
      vkernels::kernels::hip::dsa_topk_logits(
          bs, H, D, B, mt, max_seq_len, sp, dq, dkv, dw, dsl, dpt, dout);
    };
    auto r = bench_us(L, start, stop);
    double gbs = bytes / (r.median_us / 1e6) / 1e9;
    if (base_us < 0) base_us = r.median_us;
    double speedup = base_us > 0 ? base_us / r.median_us : 0;
    std::printf("  %6d %9.1f %9.1f %9.1f %8.1fx\n", sp, r.min_us,
                r.median_us, gbs, speedup);
  }
  std::printf("  (split_kv is perf-only and grouping-independent -- the\n"
              "        reference logit is identical across splits; see\n"
              "        test_dsa_topk_correct.hip case split=2. Max split\n"
              "        here is ceildiv(max_seq_len,B)=%d. The integrator\n"
              "        should set split_kv = min(ceildiv(max_seq_len,B),\n"
              "        CUs/batch_size) -- see dsa.hpp::dsa_topk_logits_split_for.)\n",
              (max_seq_len + B - 1) / B);

  check_hip(hipFree(dq), "fq");
  check_hip(hipFree(dkv), "fkv");
  check_hip(hipFree(dw), "fw");
  check_hip(hipFree(dsl), "fsl");
  check_hip(hipFree(dpt), "fpt");
  check_hip(hipFree(dout), "fout");
}

// ---------------------------------------------------------------------------
// Variant comparison at the GLM-5.3 decode shape (H=32, D=128, B=64,
// mt=8 -> 512 tokens, bs=1, split=1). The auto dispatcher now picks the
// bf16-MFMA kernel (smallest footprint, Matrix-Core) over the fp32-Q and
// fp8-Q scalar GEMVs; this prints median-us + speedup-vs-fp32 for all
// three forced variants so the win is visible end-to-end. mfma is only
// run if dsa_topk_logits_fits_lds_mfma admits the shape (it does at H=32).
static void bench_variants(const GpuInfo& info, hipEvent_t start,
                           hipEvent_t stop) {
  const int bs = 1, H = 32, D = 128, B = 64, mt = 8, nb = 8, split = 1;
  const int max_seq_len = mt * B;   // 512
  const size_t nq = (size_t)bs * H * D;
  const size_t nkvbytes = (size_t)nb * B * (D + 4);
  const size_t nw = (size_t)bs * H;
  const size_t nout = (size_t)bs * max_seq_len;

  std::vector<uint8_t> q_u8(nq), kv_u8;
  std::vector<float> k_scale;
  build_kvcache(kv_u8, k_scale, nb, B, D);
  for (size_t i = 0; i < nq; ++i) q_u8[i] = rnd_fp8(1, (int)i);
  std::vector<float> weight(nw);
  for (size_t i = 0; i < nw; ++i) weight[i] = rnd(4, (int)i);
  std::vector<int32_t> sl(bs, max_seq_len);
  std::vector<int32_t> pt((size_t)bs * mt);
  for (int b = 0; b < bs; ++b)
    for (int i = 0; i < mt; ++i)
      pt[(size_t)b * mt + i] = (int32_t)(((unsigned)(b * 7 + i * 13)) %
                                         (unsigned)nb);

  uint8_t *dq, *dkv, *dout;
  float *dw;
  int32_t *dsl, *dpt;
  check_hip(hipMalloc(&dq,   nq), "q");
  check_hip(hipMalloc(&dkv,  nkvbytes), "kv");
  check_hip(hipMalloc(&dw,   nw * 4), "w");
  check_hip(hipMalloc(&dsl,  (size_t)bs * 4), "sl");
  check_hip(hipMalloc(&dpt,  (size_t)bs * mt * 4), "pt");
  check_hip(hipMalloc(&dout, nout * 4), "out");
  check_hip(hipMemcpy(dq,   q_u8.data(),  nq, hipMemcpyHostToDevice), "cpyq");
  check_hip(hipMemcpy(dkv,  kv_u8.data(), nkvbytes, hipMemcpyHostToDevice),
            "cpykv");
  check_hip(hipMemcpy(dw,   weight.data(), nw * 4, hipMemcpyHostToDevice),
            "cpyw");
  check_hip(hipMemcpy(dsl,  sl.data(), (size_t)bs * 4, hipMemcpyHostToDevice),
            "cpysl");
  check_hip(hipMemcpy(dpt,  pt.data(), (size_t)bs * mt * 4,
            hipMemcpyHostToDevice), "cpypt");

  struct Ent { const char* name; int variant; };
  const Ent ents[] = {
      {"auto", 0}, {"fp32", 1}, {"fp8q", 2}, {"mfma", 3},
  };
  std::printf("\n=== hip::dsa_topk_logits variant comparison "
              "(bs=%d H=%d D=%d B=%d max_seq_len=%d, %d CUs) ===\n",
              bs, H, D, B, max_seq_len, info.cus);
  std::printf("  %6s %9s %9s %9s\n", "var", "us(min)", "us(med)", "vs fp32");
  double fp32_us = -1;
  for (const auto& e : ents) {
    auto L = [&] {
      vkernels::kernels::hip::dsa_topk_logits_with_variant(
          bs, H, D, B, mt, max_seq_len, split, dq, dkv, dw, dsl, dpt, dout,
          e.variant);
    };
    check_hip(hipMemset(dout, 0, nout * sizeof(float)), "zero out");
    auto r = bench_us(L, start, stop);
    if (e.variant == 1) fp32_us = r.median_us;
    double sp = (e.variant != 1 && fp32_us > 0) ? fp32_us / r.median_us
                                                : 1.0;
    std::printf("  %6s %9.1f %9.1f %8.2fx\n", e.name, r.min_us,
                r.median_us, sp);
  }
  std::printf("  (auto dispatches mfma here -- the SMALLEST-variant + "
              "Matrix-Core path.\n"
              "   fp32-Q stages Q as fp32 once (49,536 B),\n"
              "   fp8-Q stages Q raw + dequants on the fly (41,472 B),\n"
              "   mfma   stages Q transposed bf16 once + bf16 K-tile "
              "(16,768 B).\n"
              "   See dsa.hpp::dsa_topk_logits_fits_lds{,_fp8q,_mfma}.)\n");

  check_hip(hipFree(dq), "fq");
  check_hip(hipFree(dkv), "fkv");
  check_hip(hipFree(dw), "fw");
  check_hip(hipFree(dsl), "fsl");
  check_hip(hipFree(dpt), "fpt");
  check_hip(hipFree(dout), "fout");
}

int main() {
  const GpuInfo info = get_gpu_info();
  std::printf("GPU: %s (arch=%s)  %d CUs,  roof %.0f TFLOP/s bf16,"
              " %.0f GB/s HBM3, ridge ~%.0f FLOP/B\n",
              info.name.c_str(),
              info.arch == 942 ? "gfx942" :
              info.arch == 90  ? "gfx90a" : "?",
              info.cus, info.tflops, info.bw,
              info.tflops * 1e3 / info.bw);

  hipEvent_t start, stop;
  check_hip(hipEventCreate(&start), "ev_start");
  check_hip(hipEventCreate(&stop), "ev_stop");

  bench_indexer(info, start, stop);
  bench_split(info, start, stop);
  bench_variants(info, start, stop);

  check_hip(hipEventDestroy(start), "d_start");
  check_hip(hipEventDestroy(stop), "d_stop");
  return 0;
}

// meta/benchmarks/bench_gemm_bf16.cu
//
// Micro-benchmark for the CUDA wmma bf16 GEMM (issue #29 port) on NVIDIA.
// Reports, per Kimi-K3 projection shape:
//   * median / min latency (us),
//   * achieved TFLOP/s  = 2*M*N*K / t,
//   * effective GB/s    = actual HBM bytes / t  (A read once per N-tile,
//     B once per M-tile, C once; no cross-tile reuse),
//   * arithmetic intensity and the binding resource vs the GB10 roof.
//
// It also runs a per-shape tile autotuner over the compiled tiles via the
// explicit-config dispatcher cuda::gemm_bf16_with_config, so the
// gemm_bf16_config_for table in src/c can be regenerated on device.
//
// On CUDA 13 the clockRate / memoryClockRate fields were removed from
// cudaDeviceProp, so the memory roof is MEASURED here with a read-only copy
// kernel and the bf16 compute roof is MEASURED with a register-resident
// wmma throughput micro-kernel (the tiled GEMM itself is memory-bound at
// AI ~= 2*bn ~= 32 on GB10, right at the ridge, so it cannot probe the
// compute roof). Both are printed so the roofline is grounded in
// measurement, not datasheet arithmetic.
//
// Built only with VKERNELS_HAS_CUDA (and NOT VKERNELS_HAS_HIP -- on a
// dual-GPU box the .hip bench already provides gemm_bf16_bench).

#include <cuda_runtime.h>

#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <functional>
#include <string>
#include <vector>

#include "vkernels/kernels/gemm_bf16.hpp"

// Explicit-tile dispatcher (not in the public header; forward-declared
// here, same as test_gemm_bf16_correct.cu).
namespace vkernels::kernels::cuda {
void gemm_bf16_with_config(std::size_t M, std::size_t N, std::size_t K,
                           float alpha, const uint16_t* A,
                           const uint16_t* B, float beta, uint16_t* C,
                           int bm, int bn, int bk, int threads);
}  // namespace vkernels::kernels::cuda

static void check_cuda(cudaError_t err, const char* ctx) {
  if (err != cudaSuccess) {
    std::fprintf(stderr, "CUDA error (%s): %s\n", ctx, cudaGetErrorString(err));
    std::exit(1);
  }
}

struct GpuInfo { std::string name; int sms; double tflops, bw; };

// Read-only copy micro-kernel: every thread loads + stores a contiguous
// uint4 stride. Used to measure the practical global-memory bandwidth.
__global__ void copy_k(const uint4* __restrict__ src, uint4* __restrict__ dst,
                       int n4) {
  for (int i = blockIdx.x * blockDim.x + threadIdx.x; i < n4;
       i += gridDim.x * blockDim.x)
    dst[i] = src[i];
}

// Compute-roof micro-kernel: each warp performs `rounds` independent
// 16x16x16 bf16 wmma accumulations on register-resident fragments that are
// filled ONCE and reused, so HBM traffic is O(1) and the kernel is purely
// compute-bound. One warp per block; many blocks to load the SMs. This is
// the only honest way to measure a bf16 compute peak for wmma on this device
// -- the tiled GEMM itself is memory-bound at AI ~= 2*bn (~32 on GB10, right
// at the memory ridge), so it can never be used to probe the compute roof.
#include <cuda_bf16.h>
#include <mma.h>
__global__ void wmma_throughput_k(int rounds, float* __restrict__ sink) {
  using namespace nvcuda::wmma;
  const int warp = (blockIdx.x * blockDim.x + threadIdx.x) / 32;
  const int lane = threadIdx.x & 31;
  fragment<matrix_a, 16, 16, 16, __nv_bfloat16, row_major> a;
  fragment<matrix_b, 16, 16, 16, __nv_bfloat16, row_major> b;
  fragment<accumulator, 16, 16, 16, float> c;
  fill_fragment(a, __float2bfloat16(1.0f));
  fill_fragment(b, __float2bfloat16(1.0f));
  fill_fragment(c, 0.0f);
#pragma unroll 1
  for (int r = 0; r < rounds; ++r) mma_sync(c, a, b, c);
  if (lane == 0) sink[warp] = c.x[0];   // defeat dead-code elimination
}

static double measure_bw(size_t bytes) {
  const int n4 = (int)(bytes / sizeof(uint4));
  uint4 *dS, *dD;
  check_cuda(cudaMalloc(&dS, (size_t)n4 * sizeof(uint4)), "bw src");
  check_cuda(cudaMalloc(&dD, (size_t)n4 * sizeof(uint4)), "bw dst");
  check_cuda(cudaMemset(dS, 0xAB, (size_t)n4 * sizeof(uint4)), "bw fill");
  int block = 256, grid = std::min(2048, (n4 + block - 1) / block);
  copy_k<<<grid, block>>>(dS, dD, n4);
  check_cuda(cudaDeviceSynchronize(), "bw warmup");
  // Time several repeats; each repeat copies the same buffer (bandwidth, not
  // a one-shot transfer), so we divide by the number of repeats.
  const int reps = 50;
  cudaEvent_t s, e; cudaEventCreate(&s); cudaEventCreate(&e);
  cudaEventRecord(s);
  for (int r = 0; r < reps; ++r) copy_k<<<grid, block>>>(dS, dD, n4);
  cudaEventRecord(e);
  cudaEventSynchronize(e);
  float ms = 0; cudaEventElapsedTime(&ms, s, e);
  cudaEventDestroy(s); cudaEventDestroy(e);
  double gb = (double)bytes * 2.0 * reps / 1e9;   // read + write
  double bw = gb / (ms / 1e3);
  cudaFree(dS); cudaFree(dD);
  return bw;
}

// Probe the bf16 compute roof with a register-resident wmma micro-kernel
// (see wmma_throughput_k above). Returns the achieved median TFLOP/s as an
// empirical peak -- independent of the memory-bound tiled GEMM.
static double measure_tflops(int sms, cudaEvent_t start, cudaEvent_t stop) {
  const int rounds = 100000;          // MMAs per warp; dominates launch oh
  const int blocks = sms * 16;        // one warp/block, load the SMs
  const int warps = blocks;           // 1 warp/block
  float* sink = nullptr;
  check_cuda(cudaMalloc(&sink, (size_t)warps * sizeof(float)), "pk sink");
  for (int i = 0; i < 3; ++i)         // warmup
    wmma_throughput_k<<<blocks, 32>>>(rounds, sink);
  check_cuda(cudaDeviceSynchronize(), "pk warmup");
  std::vector<float> ts;
  for (int i = 0; i < 30; ++i) {
    cudaEventRecord(start);
    wmma_throughput_k<<<blocks, 32>>>(rounds, sink);
    cudaEventRecord(stop);
    cudaEventSynchronize(stop);
    float ms = 0; cudaEventElapsedTime(&ms, start, stop);
    ts.push_back(ms * 1000.0f);
  }
  std::sort(ts.begin(), ts.end());
  double med = ts[ts.size() / 2];
  cudaFree(sink);
  // FLOPs = warps * rounds * 2*(16^3) for the 16x16x16 mma.
  double flops = (double)warps * rounds * 2.0 * 4096.0;
  return flops / (med / 1e6) / 1e12;
}

static GpuInfo get_gpu_info(cudaEvent_t start, cudaEvent_t stop) {
  cudaDeviceProp p;
  check_cuda(cudaGetDeviceProperties(&p, 0), "props");
  GpuInfo i;
  i.name = p.name;
  i.sms = p.multiProcessorCount;
  i.bw = measure_bw(512ULL * 1024 * 1024);     // 512 MiB read/write
  i.tflops = measure_tflops(i.sms, start, stop);  // empirical bf16 peak
  return i;
}

struct BenchResult { double min_us, median_us, mean_us; };

static BenchResult bench_us(const std::function<void()>& launch,
                            cudaEvent_t start, cudaEvent_t stop,
                            int warmup = 5, int max_iters = 500) {
  (void)cudaDeviceSynchronize();
  for (int i = 0; i < warmup; ++i) launch();
  (void)cudaDeviceSynchronize();           // drain warmup before timing
  int iters = 20;
  while (iters <= max_iters) {
    std::vector<float> times;
    for (int i = 0; i < iters; ++i) {
      cudaEventRecord(start);
      launch();
      cudaEventRecord(stop);
      cudaEventSynchronize(stop);
      float ms = 0;
      cudaEventElapsedTime(&ms, start, stop);
      // On GB10 the driver occasionally returns ms==0 from
      // cudaEventElapsedTime on a kernel that plainly takes >0. A zero is
      // always spurious here -- drop it before it can poison the median or
      // inflate the stddev/mean ratio (which would otherwise force the
      // adaptive loop to grow until the zeros dominate).
      if (ms > 0.0f) times.push_back(ms * 1000.0f);
    }
    // If the whole batch came back zero (a persistent driver glitch),
    // clear any sticky error and retry the batch once.
    if (times.empty()) {
      (void)cudaGetLastError();
      for (int i = 0; i < iters; ++i) {
        cudaEventRecord(start);
        launch();
        cudaEventRecord(stop);
        cudaEventSynchronize(stop);
        float ms = 0;
        cudaEventElapsedTime(&ms, start, stop);
        if (ms > 0.0f) times.push_back(ms * 1000.0f);
      }
    }
    if (times.empty()) break;             // give up, fall back to chrono
    double sum = 0;
    for (double t : times) sum += t;
    double mean = sum / times.size();
    double sum2 = 0;
    for (double t : times) sum2 += t * t;
    double var = sum2 / times.size() - mean * mean;
    double stddev = std::sqrt(std::max(0.0, var));
    if (stddev / mean < 0.03 || iters >= max_iters) {
      std::sort(times.begin(), times.end());
      return {times[0], times[times.size() / 2], mean};
    }
    iters *= 2;
  }
  // Last-resort fallback (persistent event failure): one chrono-timed
  // single launch between syncs. For kernels >= ~10 us the host-side
  // overhead is small relative to the kernel, so this stays honest.
  (void)cudaDeviceSynchronize();
  (void)cudaGetLastError();
  auto t0 = std::chrono::high_resolution_clock::now();
  launch();
  (void)cudaDeviceSynchronize();
  auto t1 = std::chrono::high_resolution_clock::now();
  double us = std::chrono::duration<double, std::micro>(t1 - t0).count();
  return {us, us, us};
}

static uint16_t f2bf(float v) {
  uint32_t b; std::memcpy(&b, &v, 4);
  b += 0x7FFFu + ((b >> 16) & 1);
  return (uint16_t)(b >> 16);
}
static float rnd(int seed, int i) {
  unsigned x = (unsigned)(seed * 2654435761u + (unsigned)i * 40503u);
  x ^= x >> 13; x *= 0x5bd1e995u; x ^= x >> 15;
  return (float)((int)x % 200000) / 100000.0f;
}

// ---------------------------------------------------------------------------
static void bench_shapes(const GpuInfo& info, cudaEvent_t start,
                         cudaEvent_t stop) {
  struct NK { int N, K; };
  const NK k3[] = {
      {6288, 7168}, {3584, 7168}, {896, 7168}, {2112, 7168}, {1536, 7168},
      {7168, 1536}, {7168, 768}, {7168, 3584}, {2304, 1536}, {3072, 512},
      {1536, 128},
  };
  std::printf("\n=== cuda::gemm_bf16 (config-selected) ===\n");
  std::printf("  %5s %6s %6s %9s %9s %9s %9s %5s  %s\n",
              "M", "N", "K", "us(min)", "us(med)", "TFLOP/s", "GB/s",
              "AI",
              "bound");
  for (int M : {5, 8, 16, 32, 64, 8192}) {
    for (const auto& s : k3) {
      const int N = s.N, K = s.K;
      std::vector<uint16_t> A((size_t)M * K), B((size_t)K * N),
          C((size_t)M * N, 0);
      for (int i = 0; i < M * K; ++i) A[i] = f2bf(rnd(1, i) * 0.5f);
      for (int i = 0; i < K * N; ++i) B[i] = f2bf(rnd(2, i) * 0.5f);
      uint16_t *dA, *dB, *dC;
      check_cuda(cudaMalloc(&dA, (size_t)M * K * 2), "A");
      check_cuda(cudaMalloc(&dB, (size_t)K * N * 2), "B");
      check_cuda(cudaMalloc(&dC, (size_t)M * N * 2), "C");
      check_cuda(cudaMemcpy(dA, A.data(), (size_t)M * K * 2,
                            cudaMemcpyHostToDevice), "cpyA");
      check_cuda(cudaMemcpy(dB, B.data(), (size_t)K * N * 2,
                            cudaMemcpyHostToDevice), "cpyB");
      auto L = [&] {
        vkernels::kernels::cuda::gemm_bf16((size_t)M, (size_t)N, (size_t)K,
                                           1.0f, dA, dB, 0.0f, dC);
      };
      // Cap at max_iters=80: on GB10/CUDA-13, batches of 160+ rapid
      // re-launches drop cudaEventElapsedTime to 0 (the autotuner, also
      // capped at 80, is unaffected). Keeps per-launch event medians.
      auto r = bench_us(L, start, stop, 5, 80);
      double tflops = 2.0 * M * N * K / (r.median_us / 1e6) / 1e12;
      // Actual HBM traffic: A read once per N-tile (ceil(N/bn)), B once per
      // M-tile (ceil(M/bm)), C written once. No cross-tile reuse, so this is
      // far above the ideal 2*(M*K+K*N+M*N) once M outgrows one M-tile.
      int cbm = 0, cbn = 0, cbk = 0, cth = 0;
      vkernels::kernels::gemm_bf16_config_for((size_t)M, (size_t)N,
                                              (size_t)K, &cbm, &cbn,
                                              &cbk, &cth);
      double bytes =
          2.0 * ((double)M * K * ((N + cbn - 1) / cbn) +
                 (double)K * N * ((M + cbm - 1) / cbm) + (double)M * N);
      double gbs = bytes / (r.median_us / 1e6) / 1e9;
      double ai = (2.0 * M * N * K) / bytes;
      const char* bound = ai < (info.tflops * 1e3 / info.bw) ? "mem" : "comp";
      std::printf("  %5d %6d %6d %9.1f %9.1f %9.3f %9.1f %5.1f  %s\n", M, N, K,
                  r.min_us, r.median_us, tflops, gbs, ai, bound);
      check_cuda(cudaFree(dA), "fA"); check_cuda(cudaFree(dB), "fB");
      check_cuda(cudaFree(dC), "fC");
    }
  }
  std::printf("  Roof: %.0f TFLOP/s bf16 (empirical), %.0f GB/s (measured), "
              "ridge ~%.0f FLOP/B\n",
              info.tflops, info.bw, info.tflops * 1e3 / info.bw);
}

// ---------------------------------------------------------------------------
// Per-shape autotuner: sweep ALL compiled tiles at EVERY serving M and print
// the full matrix (us median) plus the best tile, so gemm_bf16_config_for can
// be regenerated from measured data rather than projection.
static void autotune(const GpuInfo& info, cudaEvent_t start, cudaEvent_t stop) {
  (void)info;
  struct NK { int N, K; };
  const NK k3[] = {
      {6288, 7168}, {3584, 7168}, {896, 7168}, {2112, 7168}, {1536, 7168},
      {7168, 1536}, {7168, 768}, {7168, 3584}, {2304, 1536}, {3072, 512},
      {1536, 128},
  };
  struct Cfg { int bm, bn; };
  const Cfg cfgs[] = {{16, 16}, {16, 64}, {16, 128}, {32, 64}, {32, 128},
                      {64, 64},  {64, 128}};
  constexpr int kNCfg = sizeof(cfgs) / sizeof(cfgs[0]);
  const int Ms[] = {5, 8, 16, 32, 64};
  for (int M : Ms) {
    std::printf("\n=== tile autotuner (M=%d): us(med) per tile ===\n", M);
    std::printf("  %6s %6s", "N", "K");
    for (const auto& c : cfgs) { char nm[16];
      std::snprintf(nm, sizeof(nm), "%dx%d", c.bm, c.bn);
      std::printf(" %8s", nm); }
    std::printf("  %s\n", "best");
    for (const auto& s : k3) {
      const int N = s.N, K = s.K;
      std::vector<uint16_t> A((size_t)M * K), B((size_t)K * N),
          C((size_t)M * N, 0);
      for (int i = 0; i < M * K; ++i) A[i] = f2bf(rnd(1, i) * 0.5f);
      for (int i = 0; i < K * N; ++i) B[i] = f2bf(rnd(2, i) * 0.5f);
      uint16_t *dA, *dB, *dC;
      check_cuda(cudaMalloc(&dA, (size_t)M * K * 2), "A");
      check_cuda(cudaMalloc(&dB, (size_t)K * N * 2), "B");
      check_cuda(cudaMalloc(&dC, (size_t)M * N * 2), "C");
      check_cuda(cudaMemcpy(dA, A.data(), (size_t)M * K * 2,
                            cudaMemcpyHostToDevice), "cpyA");
      check_cuda(cudaMemcpy(dB, B.data(), (size_t)K * N * 2,
                            cudaMemcpyHostToDevice), "cpyB");
      double us[kNCfg];
      int best_i = 0; double best_us = 1e18;
      for (int i = 0; i < kNCfg; ++i) {
        const auto& c = cfgs[i];
        auto L = [&] {
          vkernels::kernels::cuda::gemm_bf16_with_config(
              (size_t)M, (size_t)N, (size_t)K, 1.0f, dA, dB, 0.0f, dC,
              c.bm, c.bn, 64, (c.bm / 16) * (c.bn / 16) * 32);
        };
        auto r = bench_us(L, start, stop, 3, 80);
        us[i] = r.median_us;
        if (us[i] < best_us) { best_us = us[i]; best_i = i; }
      }
      std::printf("  %6d %6d", N, K);
      for (int i = 0; i < kNCfg; ++i) std::printf(" %9.1f", us[i]);
      std::printf("  %dx%d\n", cfgs[best_i].bm, cfgs[best_i].bn);
      check_cuda(cudaFree(dA), "fA"); check_cuda(cudaFree(dB), "fB");
      check_cuda(cudaFree(dC), "fC");
    }
  }
}

// ---------------------------------------------------------------------------
int main() {
  cudaEvent_t start, stop;
  cudaEventCreate(&start); cudaEventCreate(&stop);
  auto info = get_gpu_info(start, stop);
  std::printf("GPU: %s  SMs=%d  bf16=%.0f TFLOP/s (empirical)  "
              "mem=%.0f GB/s (measured)\n",
              info.name.c_str(), info.sms, info.tflops, info.bw);
  bench_shapes(info, start, stop);
  autotune(info, start, stop);
  cudaEventDestroy(start); cudaEventDestroy(stop);
  return 0;
}

