// against the GB10 opt-in cap). Pure arithmetic on a documented device cap.
static bool fits_lds_fp32q(int H, int D, int B) {
  const int bytes = (H * D + H + B * D + B) * 4;
  return bytes > 0 && bytes <= kGb10LdsOptin;
}

